-- Initial catalog: categories and products with their images (served from public/images/products).
-- Stable ids keep product URLs identical across environments.
-- averageRating and reviewCount keep their default (0): they are aggregates of real reviews.

INSERT INTO "categories" ("id", "name", "description", "updatedAt") VALUES
  ('cat_electronics', 'Electronics', 'Phones, computers, audio and the gadgets in between', CURRENT_TIMESTAMP),
  ('cat_clothing', 'Clothing & Shoes', 'Everyday wardrobe staples and statement pieces', CURRENT_TIMESTAMP),
  ('cat_home', 'Home & Kitchen', 'Furniture, decor and kitchen essentials', CURRENT_TIMESTAMP),
  ('cat_sports', 'Sports & Outdoors', 'Fitness, training and outdoor gear', CURRENT_TIMESTAMP),
  ('cat_beauty', 'Beauty', 'Skincare, haircare and makeup', CURRENT_TIMESTAMP),
  ('cat_accessories', 'Accessories', 'Bags, watches, jewelry and finishing touches', CURRENT_TIMESTAMP);

-- Distinct createdAt values: listings sort by createdAt, ties would make pagination non-deterministic
INSERT INTO "products" ("id", "name", "description", "price", "stock", "image", "categoryId", "featured", "createdAt", "updatedAt")
